package org.matomo.sdk.extra;

import android.content.Intent;

import org.junit.Test;

import androidx.test.core.app.ApplicationProvider;
import testhelpers.DefaultTestCase;

import static junit.framework.Assert.assertEquals;
import static junit.framework.Assert.assertNull;
import static junit.framework.Assert.assertTrue;


public class InstallReferrerReceiverTest extends DefaultTestCase {
    // How to test on a live device:
    // adb shell am broadcast -a com.android.vending.INSTALL_REFERRER -n org.matomo.demo/org.matomo.sdk.extra.InstallReferrerReceiver --es "referrer" "utm_medium%3Dpartner%26utm_campaign%3Dpart
    @Test
    public void testReceiveGooglePlay() throws Exception {
        InstallReferrerReceiver receiver = new InstallReferrerReceiver();
        Intent testIntent = new Intent("com.android.vending.INSTALL_REFERRER");
        testIntent.setPackage(ApplicationProvider.getApplicationContext().getPackageName());

        String testReferrerData1 = "utm_source=test_source&utm_medium=test_medium&utm_term=test_term&utm_content=test_content&utm_campaign=test_name";
        testIntent.putExtra(InstallReferrerReceiver.ARG_KEY_GPLAY_REFERRER, testReferrerData1);
        receiver.onReceive(ApplicationProvider.getApplicationContext().getApplicationContext(), testIntent);
        Thread.sleep(250);
        String referrerDataFromPreferences = getMatomo().getPreferences().getString(InstallReferrerReceiver.PREF_KEY_INSTALL_REFERRER_EXTRAS, null);
        assertEquals(testReferrerData1, referrerDataFromPreferences);
        assertTrue(testIntent.getBooleanExtra("forwarded", false));


        String testReferrerData2 = "pk_campaign=Email-Nov2011&pk_kwd=OrderNow";
        testIntent.putExtra(InstallReferrerReceiver.ARG_KEY_GPLAY_REFERRER, testReferrerData2);

        receiver.onReceive(ApplicationProvider.getApplicationContext().getApplicationContext(), testIntent);
        Thread.sleep(250);
        referrerDataFromPreferences = getMatomo().getPreferences().getString(InstallReferrerReceiver.PREF_KEY_INSTALL_REFERRER_EXTRAS, null);
        assertEquals(testReferrerData1, referrerDataFromPreferences);


        testIntent.putExtra("forwarded", false);
        receiver.onReceive(ApplicationProvider.getApplicationContext().getApplicationContext(), testIntent);
        Thread.sleep(250);
        referrerDataFromPreferences = getMatomo().getPreferences().getString(InstallReferrerReceiver.PREF_KEY_INSTALL_REFERRER_EXTRAS, null);
        assertEquals(testReferrerData2, referrerDataFromPreferences);
    }

    @Test
    public void testGracefulFailure() throws Exception {
        InstallReferrerReceiver receiver = new InstallReferrerReceiver();
        Intent badIntent = new Intent("bad.action");
        badIntent.setPackage(ApplicationProvider.getApplicationContext().getPackageName());

        String testReferrerData1 = "utm_source=test_source&utm_medium=test_medium&utm_term=test_term&utm_content=test_content&utm_campaign=test_name";
        badIntent.putExtra(InstallReferrerReceiver.ARG_KEY_GPLAY_REFERRER, testReferrerData1);
        receiver.onReceive(ApplicationProvider.getApplicationContext().getApplicationContext(), badIntent);
        Thread.sleep(250);
        String referrerDataFromPreferences = getMatomo().getPreferences().getString(InstallReferrerReceiver.PREF_KEY_INSTALL_REFERRER_EXTRAS, null);
        assertNull(referrerDataFromPreferences);


        Intent nullIntent = new Intent();
        nullIntent.setPackage(ApplicationProvider.getApplicationContext().getPackageName());

        testReferrerData1 = "utm_source=test_source&utm_medium=test_medium&utm_term=test_term&utm_content=test_content&utm_campaign=test_name";
        nullIntent.putExtra(InstallReferrerReceiver.ARG_KEY_GPLAY_REFERRER, testReferrerData1);
        receiver.onReceive(ApplicationProvider.getApplicationContext().getApplicationContext(), nullIntent);
        Thread.sleep(250);
        referrerDataFromPreferences = getMatomo().getPreferences().getString(InstallReferrerReceiver.PREF_KEY_INSTALL_REFERRER_EXTRAS, null);
        assertNull(referrerDataFromPreferences);
    }

}

package org.matomo.sdk.extra;

import org.json.JSONArray;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.junit.MockitoJUnitRunner;

import java.util.Locale;

import testhelpers.BaseTest;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

@RunWith(MockitoJUnitRunner.class)
public class EcommerceItemsTest extends BaseTest {

    @Test
    public void testEmptyItems() {
        EcommerceItems items = new EcommerceItems();
        assertEquals("[]", items.toJson());
    }

    @Test
    public void testAddItems() {
        Locale.setDefault(Locale.US);
        EcommerceItems items = new EcommerceItems();
        items.addItem(new EcommerceItems.Item("fake_sku").name("fake_product").category("fake_category").price(200).quantity(2));
        items.addItem(new EcommerceItems.Item("fake_sku_2").name("fake_product_2").category("fake_category_2").price(400).quantity(3));
        items.addItem(new EcommerceItems.Item("fake_sku_3"));

        String itemsJson = items.toJson();
        assertTrue(itemsJson.contains("[\"fake_sku\",\"fake_product\",\"fake_category\",\"2.00\",\"2\"]"));
        assertTrue(itemsJson.contains("[\"fake_sku_2\",\"fake_product_2\",\"fake_category_2\",\"4.00\",\"3\"]"));
        assertTrue(itemsJson.contains("[\"fake_sku_3\"]"));
    }

    @Test
    public void testRemoveItem() {
        Locale.setDefault(Locale.US);
        EcommerceItems items = new EcommerceItems();
        items.addItem(new EcommerceItems.Item("fake_sku").name("fake_product").category("fake_category").price(200).quantity(2));
        final EcommerceItems.Item item2 = new EcommerceItems.Item("fake_sku_2").name("fake_product_2").category("fake_category_2").price(400).quantity(3);
        items.addItem(item2);
        items.remove("fake_sku");

        assertEquals("[[\"fake_sku_2\",\"fake_product_2\",\"fake_category_2\",\"4.00\",\"3\"]]", items.toJson());

        items.remove(item2);
        assertEquals(new JSONArray().toString(), items.toJson());
    }

    @Test
    public void testRemoveAllItems() {
        EcommerceItems items = new EcommerceItems();
        items.addItem(new EcommerceItems.Item("fake_sku").name("fake_product").category("fake_category").price(200).quantity(2));
        items.addItem(new EcommerceItems.Item("fake_sku_2").name("fake_product_2").category("fake_category_2").price(400).quantity(3));
        items.clear();

        assertEquals("[]", items.toJson());
    }

    @Test
    public void testItem() {
        EcommerceItems.Item item = new EcommerceItems
                .Item("fake_sku")
                .name("fake_product")
                .category("fake_category")
                .price(200)
                .quantity(2);
        assertEquals("fake_sku", item.getSku());
        assertEquals("fake_product", item.getName());
        assertEquals("fake_category", item.getCategory());
        assertEquals(200, (int) item.getPrice());
        assertEquals(2, (int) item.getQuantity());
    }

}

package org.matomo.sdk.dispatcher;


import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.ArgumentMatchers;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;

import testhelpers.BaseTest;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.times;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class EventCacheTest extends BaseTest {

    @Mock EventDiskCache mEventDiskCache;
    EventCache mEventCache;

    @Before
    public void setup() throws Exception {
        super.setup();
        when(mEventDiskCache.isEmpty()).thenReturn(true);
        mEventCache = spy(new EventCache(mEventDiskCache));
    }

    @Test
    public void testClear() {
        mEventCache.add(new Event("test"));
        mEventCache.clear();
        verify(mEventDiskCache).uncache();
        assertTrue(mEventCache.isEmpty());
    }

    @Test
    public void testDrain_simple() {
        assertTrue(mEventCache.isEmpty());
        mEventCache.add(new Event("test"));
        assertFalse(mEventCache.isEmpty());
        List<Event> events = new ArrayList<>();
        mEventCache.drainTo(events);
        assertEquals("test", events.get(0).getEncodedQuery());
        assertTrue(mEventCache.isEmpty());
    }

    @Test
    public void testDrain_empty() {
        List<Event> events = new ArrayList<>();
        mEventCache.drainTo(events);
        assertTrue(events.isEmpty());
    }

    @Test
    public void testDrain_diskCache_empty() {
        List<Event> events = new ArrayList<>();
        mEventCache.drainTo(events);
        verify(mEventDiskCache, never()).uncache();
        assertTrue(events.isEmpty());
    }

    @Test
    public void testDrain_diskCache_nonempty() {
        List<Event> events = new ArrayList<>();
        when(mEventDiskCache.uncache()).thenReturn(Collections.singletonList(new Event("test")));
        mEventCache.updateState(true);
        mEventCache.drainTo(events);
        verify(mEventDiskCache).uncache();
        assertFalse(events.isEmpty());
    }

    @Test
    public void testDrain_diskCache_first() {
        mEventCache.add(new Event("3"));
        List<Event> events = new ArrayList<>();
        when(mEventDiskCache.uncache()).thenReturn(Arrays.asList(new Event("1"), new Event("2")));
        mEventCache.updateState(true);
        mEventCache.drainTo(events);
        verify(mEventDiskCache).uncache();
        assertFalse(events.isEmpty());
        assertEquals("1", events.get(0).getEncodedQuery());
        assertEquals("2", events.get(1).getEncodedQuery());
        assertEquals("3", events.get(2).getEncodedQuery());
    }

    @Test
    public void testUpdateState_online() {
        verify(mEventDiskCache, never()).uncache();
        mEventCache.updateState(true);
        mEventCache.updateState(true);
        verify(mEventDiskCache, times(2)).uncache();
    }

    @Test
    public void testUpdateState_offline() {
        assertTrue(mEventCache.isEmpty());
        mEventCache.add(new Event("test"));
        assertFalse(mEventCache.isEmpty());
        mEventCache.updateState(false);
        verify(mEventDiskCache).cache(ArgumentMatchers.anyList());

        mEventCache.updateState(false);
        verify(mEventDiskCache).cache(ArgumentMatchers.anyList());
        mEventCache.add(new Event("test"));
        mEventCache.updateState(false);
        verify(mEventDiskCache, times(2)).cache(ArgumentMatchers.anyList());
    }

    @Test
    public void testUpdateState_offline_ordering() {
        assertTrue(mEventCache.isEmpty());
        mEventCache.add(new Event("test2"));
        when(mEventDiskCache.uncache()).thenReturn(Arrays.asList(new Event("test0"), new Event("test1")));
        mEventCache.updateState(true);

        List<Event> restoredEvents = new ArrayList<>();
        mEventCache.drainTo(restoredEvents);

        assertEquals(3, restoredEvents.size());
        assertEquals("test0", restoredEvents.get(0).getEncodedQuery());
        assertEquals("test1", restoredEvents.get(1).getEncodedQuery());
        assertEquals("test2", restoredEvents.get(2).getEncodedQuery());
    }

}

package org.matomo.sdk.dispatcher;

import android.content.Context;

import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.matomo.sdk.Matomo;
import org.matomo.sdk.Tracker;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import java.io.File;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.UUID;
import java.util.concurrent.Semaphore;

import testhelpers.BaseTest;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class EventDiskCacheTest extends BaseTest {
    @Mock Matomo mMatomo;
    @Mock Tracker mTracker;
    @Mock Context mContext;
    private EventDiskCache mDiskCache;
    private File mHostFolder;
    private File mBaseCacheDir;
    private File mCacheFolder;

    @Before
    public void setup() throws Exception {
        super.setup();
        when(mTracker.getMatomo()).thenReturn(mMatomo);
        when(mMatomo.getContext()).thenReturn(mContext);
        mBaseCacheDir = new File("baseCacheDir");
        when(mContext.getCacheDir()).thenReturn(mBaseCacheDir);

        when(mTracker.getAPIUrl()).thenReturn("http://testhost/matomo.php");

        when(mTracker.getOfflineCacheAge()).thenReturn(0L);

        mCacheFolder = new File(mBaseCacheDir, "piwik_cache");
        mHostFolder = new File(mCacheFolder, "testhost");

        mDiskCache = new EventDiskCache(mTracker);
    }

    @SuppressWarnings("ResultOfMethodCallIgnored")
    @After
    public void tearDown() throws Exception {
        super.tearDown();
        if (mHostFolder.exists()) {
            for (File file : mHostFolder.listFiles())
                file.delete();
        }
        mHostFolder.delete();
        mCacheFolder.delete();
        mBaseCacheDir.delete();
    }

    @Test
    public void testIsEmpty() {
        assertTrue(mDiskCache.isEmpty());
        mDiskCache.cache(Collections.singletonList(new Event("test")));
        assertFalse(mDiskCache.isEmpty());
    }

    @Test
    public void testCachePath() {
        mDiskCache.cache(Collections.singletonList(new Event(1000, "test")));
        File cacheFolder = new File(mBaseCacheDir, "piwik_cache");
        File hostFolder = new File(cacheFolder, "testhost");
        assertTrue(hostFolder.exists());
        assertEquals(1, hostFolder.listFiles().length);
    }

    @Test
    public void testCacheFileName() {
        mDiskCache.cache(Arrays.asList(new Event(1234567890, "test"), new Event(987654321, "test2")));
        File cacheFile = new File(mHostFolder, "events_987654321");
        assertTrue(cacheFile.exists());
        mDiskCache.uncache();
        assertFalse(cacheFile.exists());
    }

    @Test
    public void testCaching() {
        Event event1 = new Event(1, "test");
        Event event2 = new Event(2, "test");
        mDiskCache.cache(Arrays.asList(event1, event2));
        final List<Event> events = mDiskCache.uncache();
        assertEquals(2, events.size());
        assertEquals(event1, events.get(0));
        assertEquals(event2, events.get(1));
    }

    @Test
    public void testCaching_empty() {
        mDiskCache.cache(Collections.emptyList());
    }

    @Test
    public void testOrder() {
        Event event1 = new Event(1, "test");
        Event event2 = new Event(2, "test");
        mDiskCache.cache(Arrays.asList(event1, event2));
        Event event3 = new Event(3, "test");
        Event event4 = new Event(4, "test");
        mDiskCache.cache(Arrays.asList(event3, event4));
        final List<Event> events = mDiskCache.uncache();
        assertEquals(4, events.size());
        assertEquals(event1, events.get(0));
        assertEquals(event2, events.get(1));
        assertEquals(event3, events.get(2));
        assertEquals(event4, events.get(3));
    }

    @Test
    public void testMaxAge_positive_allStale() {
        when(mTracker.getOfflineCacheAge()).thenReturn(10 * 1000L);
        mDiskCache = new EventDiskCache(mTracker);
        Event event1 = new Event(1, "test");
        Event event2 = new Event(2, "test");
        mDiskCache.cache(Arrays.asList(event1, event2));
        assertEquals(0, mHostFolder.listFiles().length);
        final List<Event> events = mDiskCache.uncache();
        assertEquals(0, events.size());
    }

    @Test
    public void testMaxAge_positive_singleContainer() {
        when(mTracker.getOfflineCacheAge()).thenReturn(10 * 1000L);
        mDiskCache = new EventDiskCache(mTracker);
        Event event1 = new Event(System.currentTimeMillis() - 60 * 1000, "test");
        Event event2 = new Event(System.currentTimeMillis(), "test");
        Event event3 = new Event(2 * System.currentTimeMillis(), "test");
        mDiskCache.cache(Arrays.asList(event1, event2, event3));
        final List<Event> events = mDiskCache.uncache();
        assertEquals(2, events.size());
        assertEquals(event2, events.get(0));
        assertEquals(event3, events.get(1));
    }

    @Test
    public void testMaxAge_positive_multipleContainer() {
        when(mTracker.getOfflineCacheAge()).thenReturn(10 * 1000L);
        mDiskCache = new EventDiskCache(mTracker);
        Event event1 = new Event(System.currentTimeMillis() - 20 * 1000, "test");
        Event event2 = new Event(System.currentTimeMillis() - 15 * 1000, "test");
        mDiskCache.cache(Arrays.asList(event1, event2));
        Event event3 = new Event(System.currentTimeMillis() - 5 * 1000, "test");
        Event event4 = new Event(System.currentTimeMillis() - 2 * 1000, "test");
        mDiskCache.cache(Arrays.asList(event3, event4));
        final List<Event> events = mDiskCache.uncache();
        assertEquals(2, events.size());
        assertEquals(event3, events.get(0));
        assertEquals(event4, events.get(1));
    }

    @Test
    public void testMaxAge_unlimited() {
        when(mTracker.getOfflineCacheAge()).thenReturn(0L);
        mDiskCache = new EventDiskCache(mTracker);
        Event event1 = new Event(-System.currentTimeMillis(), "test1");
        Event event2 = new Event(0, "test2");
        Event event3 = new Event(System.currentTimeMillis(), "test3");
        Event event4 = new Event(2 * System.currentTimeMillis(), "test3");
        mDiskCache.cache(Arrays.asList(event1, event2, event3, event4));
        final List<Event> events = mDiskCache.uncache();
        assertEquals(4, events.size());
        assertEquals(event1, events.get(0));
        assertEquals(event2, events.get(1));
        assertEquals(event3, events.get(2));
        assertEquals(event4, events.get(3));
    }

    @Test
    public void testMaxAge_negative_cachingDisabled() {
        when(mTracker.getOfflineCacheAge()).thenReturn(-1L);
        mDiskCache = new EventDiskCache(mTracker);
        Event event0 = new Event(-System.currentTimeMillis(), "test");
        Event event1 = new Event(0, "test");
        Event event2 = new Event(System.currentTimeMillis(), "test");
        Event event3 = new Event(2 * System.currentTimeMillis(), "test");
        mDiskCache.cache(Arrays.asList(event0, event1, event2, event3));
        final List<Event> events = mDiskCache.uncache();
        assertEquals(0, events.size());
    }

    @Test
    public void testClearDataOnceEvenIfDisabled() {
        Event event1 = new Event(0, "test");
        Event event2 = new Event(System.currentTimeMillis(), "test");
        mDiskCache.cache(Arrays.asList(event1, event2));
        assertFalse(mDiskCache.isEmpty());
        mDiskCache = new EventDiskCache(mTracker);
        assertFalse(mDiskCache.isEmpty());
        when(mTracker.getOfflineCacheAge()).thenReturn(-1L);
        mDiskCache = new EventDiskCache(mTracker);
        assertTrue(mDiskCache.isEmpty());
    }

    @Test
    public void testMaxSize_limited() {
        when(mTracker.getOfflineCacheSize()).thenReturn(1024L);
        mDiskCache = new EventDiskCache(mTracker);
        for (int j = 0; j < 4; j++) {
            List<Event> events = new ArrayList<>();
            for (int k = 0; k < 10; k++) {
                events.add(new Event(System.nanoTime(), "set:" + j + " " + UUID.randomUUID().toString()));
            }
            // About ~512Byte
            mDiskCache.cache(events);
        }

        assertEquals(2, mHostFolder.listFiles().length);
        final List<Event> events = mDiskCache.uncache();
        assertEquals(20, events.size());

        for (Event e : events.subList(0, 10)) {
            assertTrue(e.getEncodedQuery().startsWith("set:2"));
        }
        for (Event e : events.subList(10, 20)) {
            assertTrue(e.getEncodedQuery().startsWith("set:3"));
        }
    }

    @Test
    public void testMaxSize_disabled() {
        when(mTracker.getOfflineCacheSize()).thenReturn(0L);
        mDiskCache = new EventDiskCache(mTracker);
        for (int j = 0; j < 10; j++) {
            List<Event> events = new ArrayList<>();
            for (int k = 0; k < 1000; k++) {
                events.add(new Event(System.nanoTime(), UUID.randomUUID().toString()));
            }
            mDiskCache.cache(events);
        }

        assertEquals(10, mHostFolder.listFiles().length);
        final List<Event> events = mDiskCache.uncache();
        assertEquals(10000, events.size());
    }

    @Test
    public void stressTest_singles() throws Exception {
        final Semaphore sem = new Semaphore(0);
        for (int i = 0; i < 8; i++) {
            new Thread(() -> {
                for (int j = 0; j < 100; j++) {
                    Event event1 = new Event(System.nanoTime(), UUID.randomUUID().toString());
                    mDiskCache.cache(Collections.singletonList(event1));
                }
                sem.release(1);
            }).start();
        }
        sem.acquire(8);
        assertEquals(800, mHostFolder.listFiles().length);
        final List<Event> events = mDiskCache.uncache();
        assertEquals(800, events.size());
        assertEquals(0, mHostFolder.listFiles().length);
    }

    @Test
    public void stressTest_multi() throws Exception {
        final Semaphore sem = new Semaphore(0);
        for (int i = 0; i < 4; i++) {
            new Thread(() -> {
                for (int j = 0; j < 10; j++) {
                    List<Event> events = new ArrayList<>();
                    for (int k = 0; k < 1000; k++) {
                        events.add(new Event(System.nanoTime(), UUID.randomUUID().toString()));
                    }
                    mDiskCache.cache(events);
                }
                sem.release(1);
            }).start();
        }
        sem.acquire(4);
        assertEquals(40, mHostFolder.listFiles().length);
        final List<Event> events = mDiskCache.uncache();
        assertEquals(40000, events.size());
        assertEquals(0, mHostFolder.listFiles().length);
    }

    @Test
    public void testOfflineMode_issue_271() {
        when(mTracker.getOfflineCacheSize()).thenReturn(4096L);
        mDiskCache = new EventDiskCache(mTracker);

        // Hit limit
        for (int i = 0; i < 2; i++) {
            List<Event> batch1 = new ArrayList<>();
            for (int k = 0; k < 100; k++) {
                batch1.add(new Event(System.nanoTime(), UUID.randomUUID().toString()));
            }
            mDiskCache.cache(batch1);
        }

        final List<Event> events1 = mDiskCache.uncache();
        assertEquals(100, events1.size());

        // Hit limit again
        List<Event> batch2 = new ArrayList<>();
        for (int k = 0; k < 100; k++) {
            batch2.add(new Event(System.nanoTime(), UUID.randomUUID().toString()));
        }
        mDiskCache.cache(batch2);

        final List<Event> events2 = mDiskCache.uncache();
        assertEquals(100, events2.size());
    }
}

package org.matomo.sdk.extra;

import android.content.BroadcastReceiver;
import android.content.Context;
import android.content.Intent;

import org.matomo.sdk.Matomo;

import java.util.Collections;
import java.util.List;

import timber.log.Timber;


public class InstallReferrerReceiver extends BroadcastReceiver {
    private static final String TAG = Matomo.tag(InstallReferrerReceiver.class);

    // Google Play
    static final String REFERRER_SOURCE_GPLAY = "com.android.vending.INSTALL_REFERRER";
    static final String ARG_KEY_GPLAY_REFERRER = "referrer";

    static final String PREF_KEY_INSTALL_REFERRER_EXTRAS = "referrer.extras";
    static final List<String> RESPONSIBILITIES = Collections.singletonList(REFERRER_SOURCE_GPLAY);

    @Override
    public void onReceive(Context context, Intent intent) {
        Timber.tag(TAG).d(intent.toString());
        if (intent.getAction() == null || !RESPONSIBILITIES.contains(intent.getAction())) {
            Timber.tag(TAG).w("Got called outside our responsibilities: %s", intent.getAction());
            return;
        }
        if (intent.getBooleanExtra("forwarded", false)) {
            Timber.tag(TAG).d("Dropping forwarded intent");
            return;
        }
        if (intent.getAction().equals(REFERRER_SOURCE_GPLAY)) {
            String referrer = intent.getStringExtra(ARG_KEY_GPLAY_REFERRER);
            if (referrer != null) {
                final PendingResult result = goAsync();
                new Thread(() -> {
                    Matomo.getInstance(context.getApplicationContext()).getPreferences().edit().putString(PREF_KEY_INSTALL_REFERRER_EXTRAS, referrer).apply();
                    Timber.tag(TAG).d("Stored Google Play referrer extras: %s", referrer);
                    result.finish();
                }).start();
            }
        }
        // Forward to other possible recipients
        intent.setComponent(null);
        intent.setPackage(context.getPackageName());
        intent.putExtra("forwarded", true);
        context.sendBroadcast(intent);
    }
}

