        tracker.setSessionTimeout(0);
        TestHelper.sleep(1);
        TrackHelper.track().screen("test3").with(tracker);
        assertThat(tracker.getLastEventX().get(QueryParams.SESSION_START), notNullValue());

        tracker.setSessionTimeout(10000);
