import org.json.JSONObject;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.junit.MockitoJUnitRunner;

import okhttp3.mockwebserver.Dispatcher;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import testhelpers.BaseTest;
import testhelpers.TestHelper;

import static org.hamcrest.MatcherAssert.assertThat;
import static org.hamcrest.Matchers.not;
import static org.hamcrest.Matchers.nullValue;
import static org.hamcrest.core.Is.is;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import androidx.annotation.NonNull;

@RunWith(MockitoJUnitRunner.class)
public class DefaultPacketSenderTest extends BaseTest {

    DefaultPacketSender mDefaultPacketSender;
    MockWebServer mMockWebServer;

    @Before
    public void setup() throws Exception {
        super.setup();
        mDefaultPacketSender = new DefaultPacketSender();
        mMockWebServer = new MockWebServer();
    }

    @After
    public void tearDown() throws Exception {
        mMockWebServer.close();
        super.tearDown();
    }

    @Test
    public void testDispatch() throws Exception {
        mMockWebServer.start();

        Packet packet = mock(Packet.class);
        when(packet.getTargetURL()).thenReturn(mMockWebServer.url("/").toString());
        JSONObject jsonObject = new JSONObject();
        jsonObject.put("key", "value");
        when(packet.getPostData()).thenReturn(jsonObject);

        mMockWebServer.enqueue(new MockResponse());
        mDefaultPacketSender.send(packet);

        final RecordedRequest recordedRequest = mMockWebServer.takeRequest();
        assertThat(recordedRequest, is(not(nullValue())));

        String body = recordedRequest.getBody().readUtf8();
        assertThat(jsonObject.toString(), is(body));
        assertThat(recordedRequest.getHeader("Content-Encoding"), is((nullValue())));
    }

    @Test
    public void testGzip() throws Exception {
        mMockWebServer.start();

        Packet packet = mock(Packet.class);
        when(packet.getTargetURL()).thenReturn(mMockWebServer.url("/").toString());
        JSONObject jsonObject = new JSONObject();
        jsonObject.put("key", "value");
        when(packet.getPostData()).thenReturn(jsonObject);

        mMockWebServer.enqueue(new MockResponse());
        mDefaultPacketSender.send(packet);
        assertThat(mMockWebServer.takeRequest().getHeader("Content-Encoding"), is((nullValue())));

        mDefaultPacketSender.setGzipData(true);

        mMockWebServer.enqueue(new MockResponse());
        mDefaultPacketSender.send(packet);
        assertThat(mMockWebServer.takeRequest().getHeader("Content-Encoding"), is("gzip"));
    }

    @Test
    public void testTimeout() throws Exception {
        mMockWebServer.start();

        Packet packet = mock(Packet.class);
        when(packet.getTargetURL()).thenReturn(mMockWebServer.url("/").toString());

        mDefaultPacketSender.setTimeout(50);
        mMockWebServer.setDispatcher(new Dispatcher() {
            @NonNull
            @Override
            public MockResponse dispatch(@NonNull RecordedRequest recordedRequest) {
                TestHelper.sleep(100);
                return new MockResponse();
            }
        });
        assertThat(mDefaultPacketSender.send(packet), is(false));

        mMockWebServer.setDispatcher(new Dispatcher() {
            @NonNull
            @Override
            public MockResponse dispatch(@NonNull RecordedRequest recordedRequest) {
                return new MockResponse();
            }
        });
        assertThat(mDefaultPacketSender.send(packet), is(true));
    }
}

package org.matomo.sdk.extra;

import org.junit.Test;
import org.junit.runner.RunWith;
import org.matomo.sdk.TrackMe;
import org.matomo.sdk.Tracker;
import org.mockito.ArgumentCaptor;
import org.mockito.junit.MockitoJUnitRunner;

import static org.hamcrest.CoreMatchers.is;
import static org.hamcrest.CoreMatchers.notNullValue;
import static org.hamcrest.CoreMatchers.nullValue;
import static org.hamcrest.MatcherAssert.assertThat;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;

@RunWith(MockitoJUnitRunner.class)
public class DimensionQueueTest {
    Tracker mTracker = mock(Tracker.class);
    ArgumentCaptor<Tracker.Callback> mCaptor = ArgumentCaptor.forClass(Tracker.Callback.class);

    @Test
    public void testEmpty() {
        new DimensionQueue(mTracker);
        verify(mTracker).addTrackingCallback(mCaptor.capture());

        TrackMe pre = new TrackMe();
        TrackMe post = mCaptor.getValue().onTrack(pre);
        assertThat(post, notNullValue());
        assertThat(pre, is(post));
    }

    @Test
    public void testCallback() {
        DimensionQueue queue = new DimensionQueue(mTracker);
        verify(mTracker).addTrackingCallback(mCaptor.capture());

        queue.add(1, "test1");
        queue.add(2, "test2");
        TrackMe pre = new TrackMe();
        TrackMe post = mCaptor.getValue().onTrack(pre);
        assertThat(post, notNullValue());
        assertThat(pre, is(post));
        assertThat(CustomDimension.getDimension(post, 1), is("test1"));
        assertThat(CustomDimension.getDimension(post, 2), is("test2"));
    }

    @Test
    public void testCollision() {
        DimensionQueue queue = new DimensionQueue(mTracker);
        verify(mTracker).addTrackingCallback(mCaptor.capture());

        queue.add(1, "test1");
        TrackMe pre = new TrackMe();
        CustomDimension.setDimension(pre, 1, "don't overwrite me");
        TrackMe post = mCaptor.getValue().onTrack(pre);
        assertThat(post, notNullValue());
        assertThat(pre, is(post));
        assertThat(CustomDimension.getDimension(post, 1), is("don't overwrite me"));
    }

    @Test
    public void testOverwriting() {
        DimensionQueue queue = new DimensionQueue(mTracker);
        verify(mTracker).addTrackingCallback(mCaptor.capture());

        queue.add(1, "test1");
        queue.add(1, "test3");
        queue.add(2, "test2");
        {
            TrackMe post = mCaptor.getValue().onTrack(new TrackMe());
            assertThat(post, notNullValue());
            assertThat(CustomDimension.getDimension(post, 1), is("test1"));
            assertThat(CustomDimension.getDimension(post, 2), is("test2"));
        }
        {
            TrackMe post = mCaptor.getValue().onTrack(new TrackMe());
            assertThat(post, notNullValue());
            assertThat(CustomDimension.getDimension(post, 1), is("test3"));
            assertThat(CustomDimension.getDimension(post, 2), nullValue());
        }
    }
}

package org.matomo.sdk.extra;

import android.content.Context;
